      ro: ["Fortul Masmak este construit în întregime din cărămizi de pământ uscat la soare.", "Riad găzduiește sediul central al Consiliului de Cooperare al Golfului (GCC).", "Turnul Al Faisaliyah a fost primul zgârie-nori modern construit în Arabia Saudită.", "Orașul consumă zilnic milioane de metri cubi de apă pompată de la 400 km distanță.", "Boulevard City din Riad este una dintre cele mai mari zone de divertisment din regiune.", "Populația orașului a crescut de la 150.000 în 1960 la peste 7 milioane în prezent.", "Riad este un nod rutier major, cu autostrăzi care îl leagă de Mecca, Medina și Dammam.", "Muzeul Național al Arabiei Saudite din Riad are o arhitectură inspirată de dunele de nisip."],
