      es: ["La región es famosa por las coloridas casas Qulas.", "El cercano Parque Nacional Asir ofrece una rica flora."],
      pt: ["A região é famosa pelas coloridas casas Qulas.", "O próximo Parque Nacional Asir oferece uma flora rica."],
